-- Tabla: fza_caja_pagos

DROP TABLE IF EXISTS `fza_caja_pagos`;
CREATE TABLE `fza_caja_pagos` (
  `CODIGO_EMP_PAGO` varchar(20) NOT NULL,
  `CODIGO_ALM_PAGO` varchar(10) NOT NULL,
  `CODIGO_CAJA_PAGO` varchar(10) NOT NULL,
  `SERIE_OPERACION_PAGO` varchar(20) NOT NULL,
  `NUMERO_OPERACION_PAGO` varchar(20) NOT NULL,
  `NUMERO_LINEA_PAGO` int(11) NOT NULL DEFAULT '1' COMMENT 'Orden del pago: 1, 2, 3...',
  `CODIGO_FP_CFP` varchar(10) NOT NULL COMMENT 'FK a fza_formas_pago',
  `CODIGO_DIVISA_PAGO` varchar(10) NULL DEFAULT NULL COMMENT 'Código ISO o Ticker: USD, BTC, ETH',
  `RED_BLOCKCHAIN_PAGO` varchar(50) NULL DEFAULT NULL COMMENT 'Ej: Bitcoin, Ethereum, TRC20, ERC20, Lightning',
  `FACTOR_CAMBIO_PAGO` decimal(24,8) NOT NULL DEFAULT '1.00000000' COMMENT 'Valor de conversión respecto a la moneda base',
  `IMPORTE_DIVISA_PAGO` decimal(24,8) NOT NULL DEFAULT '0.00000000' COMMENT 'Cantidad entregada en la divisa o crypto original',
  `IMPORTE_ENTREGADO_PAGO` decimal(19,6) NOT NULL DEFAULT '0.000000',
  `IMPORTE_CAMBIO_PAGO` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Solo para efectivo si entrega de más',
  `REFERENCIA_FACPAG` varchar(255) NULL DEFAULT NULL COMMENT 'Hash de Transacción (TxID), Auth Tarjeta o Referencia',
  `OBSERVACIONES_PAGO` varchar(255) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_EMP_PAGO`,`CODIGO_ALM_PAGO`,`CODIGO_CAJA_PAGO`,`SERIE_OPERACION_PAGO`,`NUMERO_OPERACION_PAGO`,`NUMERO_LINEA_PAGO`)
);
ALTER TABLE `fza_caja_pagos` ADD INDEX `FK_PAGO_FORMAP` (`CODIGO_FP_CFP`);

