-- Tabla: fza_facturas

DROP TABLE IF EXISTS `fza_facturas`;
CREATE TABLE `fza_facturas` (
  `NUMERO_FAC` varchar(20) NOT NULL COMMENT 'Número de documento',
  `SERIE_FAC` varchar(20) NOT NULL COMMENT 'Serie de documento',
  `FECHA_FAC` date NULL DEFAULT NULL COMMENT 'Fecha oficial del documento',
  `ESCONSOLIDADA_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'Si la factura se ha emitido',
  `INSTANTECONSO_FAC` datetime NULL DEFAULT NULL COMMENT 'Fecha y Hora de la consolidación',
  `TIPO_FAC` varchar(20) NULL DEFAULT 'NORMAL' COMMENT 'NORMAL, SIMPLIFICADA, RECTIFICATIVA',
  `FASE_FAC` varchar(20) NULL DEFAULT NULL COMMENT 'BORRADOR, ONLINE, OFFLINE, ERROR, ERROR_BORRADOR, VERIFICADA, CANCELADA',
  `CODIGO_EMP_FAC` varchar(8) NULL DEFAULT NULL COMMENT 'Código de empresa del emisor del documento',
  `RAZON_SOCIAL_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `NIF_EMPRESA_FAC` varchar(50) NULL DEFAULT NULL,
  `MOVIL_EMPRESA_FAC` varchar(40) NULL DEFAULT NULL,
  `EMAIL_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `DIRECCION1_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `POBLACION_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_EMPRESA_FAC` varchar(200) NULL DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_FAC` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_FAC` varchar(150) NULL DEFAULT 'España',
  `CODIGO_POSTAL_EMPRESA_FAC` varchar(15) NULL DEFAULT NULL,
  `ESRETENCIONES_EMPRESA_FAC` varchar(1) NULL DEFAULT 'S' COMMENT 'S o N si la empresa aplica retenciones como autónomos',
  `GRUPO_ZONA_IVA_EMPRESA_FAC` varchar(10) NULL DEFAULT NULL,
  `ESREGIMENESPECIALAGRICOLA_EMPRESA_FAC` varchar(1) NULL DEFAULT 'N',
  `CODIGO_CLI_FAC` varchar(10) NULL DEFAULT NULL,
  `RAZON_SOCIAL_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `NIF_CLIENTE_FAC` varchar(50) NULL DEFAULT NULL,
  `MOVIL_CLIENTE_FAC` varchar(40) NULL DEFAULT NULL,
  `EMAIL_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `DIRECCION1_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `POBLACION_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_CLIENTE_FAC` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_FAC` varchar(15) NULL DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_FAC` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_FAC` varchar(150) NULL DEFAULT 'España',
  `CODIGO_IVA_FAC` varchar(20) NULL DEFAULT NULL COMMENT 'Código de IVA de la tabla fza_ivas',
  `ESIVA_RECARGO_CLIENTE_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'S o N si el cliente tiene RE',
  `ESIVA_EXENTO_CLIENTE_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'S o N si el cliente tiene IVA EXENTO',
  `ESREGIMENESPECIALAGRICOLA_CLIENTE_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'S o N si el cliente tiene REAGP',
  `ESRETENCIONES_CLIENTE_FAC` varchar(1) NULL DEFAULT 'S' COMMENT 'S o N Si el cliente aplica retenciones',
  `TARIFA_ARTICULO_CLIENTE_FAC` varchar(10) NULL DEFAULT NULL COMMENT 'Código de la tarifa que viene del cliente o configurada por el usuario',
  `ESIMP_INCL_TARIFA_CLIENTE_FAC` varchar(1) NULL DEFAULT 'S' COMMENT 'Si el precio de la tarifa del cliente es con impuestos incl o no',
  `ESINTRACOMUNITARIO_CLIENTE_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'Si la venta es hacia un país de la UE',
  `ESIRPF_IMP_INCL_ZONA_IVA_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'Si la base del cáculo del irpf se hace desde BI o BI con impuestos',
  `ESAPLICA_RE_ZONA_IVA_FAC` varchar(1) NULL DEFAULT 'S' COMMENT 'Si el tipo de IVA aplica Recargo de Equivalencia o no',
  `ESIVAAGRICOLA_ZONA_IVA_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'Si el tipo de IVA es compatible con REAGP',
  `PALABRA_REPORTS_ZONA_IVA_FAC` varchar(10) NULL DEFAULT 'IVA' COMMENT 'Palabra que sustituye a IVA desde la tabla de fza_ivas_grupos',
  `ESVENTA_ACTIVO_FIJO_FAC` varchar(1) NULL DEFAULT 'N' COMMENT 'Sólo REAGP cuando se vende activos fijos, exime irpf',
  `PORCENTAJE_IVAN_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Normal',
  `TOTAL_IVAN_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA Normal',
  `PORCENTAJE_REN_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje RE Normal',
  `TOTAL_REN_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Normal',
  `TOTAL_BASEI_IVAN_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Base Imponible IVA Normal',
  `PORCENTAJE_IVAR_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Reducido',
  `TOTAL_IVAR_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'TotaL IVA Reducido',
  `PORCENTAJE_RER_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje RE Reducido',
  `TOTAL_RER_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Reducido',
  `TOTAL_BASEI_IVAR_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Base Imponible IVA Reducido',
  `PORCENTAJE_IVAS_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_IVAS_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA SuperReducido',
  `PORCENTAJE_RES_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_RES_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE SuperReducido',
  `TOTAL_BASEI_IVAS_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total sin IVA SuperReducido',
  `PORCENTAJE_IVAE_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Exento',
  `TOTAL_IVAE_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA Exento',
  `PORCENTAJE_REE_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA1 Exento',
  `TOTAL_REE_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Exento',
  `TOTAL_BASEI_IVAE_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total sin IVA Exento',
  `TOTAL_BASES_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Todas las bases imponibles',
  `TOTAL_IMPUESTOS_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total de todos los impuestos iva + re',
  `FORMA_PAGO_FAC` varchar(200) NULL DEFAULT NULL COMMENT 'Codigo Forma de Pago',
  `PORCENTAJE_RETENCION_FAC` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje Retenciones',
  `TOTAL_RETENCION_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Retenciones Factura',
  `TOTAL_LIQUIDO_FAC` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Factura a pagar en el acto de emisión',
  `NUMERO_FAC_ABONO_FAC` varchar(8) NULL DEFAULT NULL COMMENT 'Nro Factura Abono',
  `SERIE_FAC_ABONO_FAC` varchar(8) NULL DEFAULT NULL COMMENT 'Serie Factura Abono',
  `TEXTO_LEGAL_CLIENTE_FAC` varchar(1000) NULL DEFAULT '' COMMENT 'Texto legal desde el cliente',
  `TEXTO_LEGAL_EMPRESA_FAC` varchar(1000) NULL DEFAULT '' COMMENT 'Texto legal desde la empresa',
  `DOCUMENTO_FAC` blob NULL DEFAULT NULL COMMENT 'Documento Factura (en desuso)',
  `COMENTARIOS_FAC` varchar(1000) NULL DEFAULT '',
  `CONTADOR_LINEAS_FAC` varchar(8) NULL DEFAULT NULL COMMENT 'Contador de lineas para lineas de factura',
  `ESCREARARTICULOS_FAC` varchar(1) NULL DEFAULT NULL COMMENT 'S o N si se crean articulos desde el detalle',
  `ESDESCRIPCIONES_AMP_FAC` varchar(1) NULL DEFAULT 'S' COMMENT 'S o N si la factura contiene una descripción larga',
  `ESFECHADEENTREGA_FAC` varchar(1) NULL DEFAULT NULL COMMENT 'S o N si las descripciones tienen fecha de entrega',
  `XML_FAC` text NULL DEFAULT NULL COMMENT 'xml de la factura electrónica firmado',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_CAJERO_FAC` varchar(10) NULL DEFAULT NULL COMMENT 'Usuario que cerró el ticket (fza_usuarios)',
  `CODIGO_ALM_FAC` varchar(10) NULL DEFAULT NULL,
  `CODIGO_CAJA_FAC` varchar(10) NULL DEFAULT NULL,
  `NUMERO_OPERACION_FAC` varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (`NUMERO_FAC`,`SERIE_FAC`)
);
ALTER TABLE `fza_facturas` ADD INDEX `IDX_FACTURAS_CLIENTE_FECHA` (`CODIGO_CLI_FAC`, `FECHA_FAC`);
ALTER TABLE `fza_facturas` ADD INDEX `IDX_FACTURAS_CLI_EMP` (`CODIGO_CLI_FAC`, `CODIGO_EMP_FAC`);
