-- Tabla: fza_facturas_consolidaciones

DROP TABLE IF EXISTS `fza_facturas_consolidaciones`;
CREATE TABLE `fza_facturas_consolidaciones` (
  `ID_FACCON` int(11) NOT NULL,
  `SERIE_FAC_FACCON` varchar(20) NOT NULL,
  `NUMERO_FAC_FACCON` varchar(20) NOT NULL,
  `REQUEST_ID_CONSOLIDACION_FACCON` varchar(100) NULL DEFAULT NULL COMMENT 'ID único de la petición',
  `QUEUE_ID_CONSOLIDACION_FACCON` int(11) NULL DEFAULT NULL COMMENT 'ID de cola del sistema',
  `QUEUE_ID_CANCEL_FACCON` int(11) NULL DEFAULT NULL COMMENT 'ID de cola del documento cancelado',
  `ISSUER_IRS_ID_CONSOLIDACION_FACCON` varchar(50) NULL DEFAULT NULL COMMENT 'NIF del emisor',
  `ISSUED_TIME_FACCON` datetime NULL DEFAULT NULL COMMENT 'Fecha y hora de emisión',
  `CHAIN_NUMBER_FACCON` varchar(100) NULL DEFAULT NULL COMMENT 'Número de cadena del sistema',
  `CHAIN_HASH_FACCON` varchar(256) NULL DEFAULT NULL COMMENT 'Hash de la cadena blockchain',
  `VERIFACTU_URL_FACCON` text NULL DEFAULT NULL COMMENT 'URL de verificación en AEAT',
  `QRCODE_BASE64_FACCON` longtext NULL DEFAULT NULL COMMENT 'Código QR en base64',
  `QRCODE_PNG_FACCON` blob NULL DEFAULT NULL COMMENT 'Código QR en PNG',
  `FECHA_PROCESAMIENTO_FACCON` datetime NULL DEFAULT current_timestamp() COMMENT 'Fecha de procesamiento',
  `ESTADO_FACCON` varchar(20) NULL DEFAULT 'PROCESADO' COMMENT 'Estado del procesamiento',
  `RESPUESTA_COMPLETA_FACCON` longtext NULL DEFAULT NULL COMMENT 'JSON completo de respuesta del webservice',
  `PETICION_COMPLETA_FACCON` longtext NULL DEFAULT NULL COMMENT 'JSON completo de petición del webservice',
  PRIMARY KEY (`ID_FACCON`)
);
ALTER TABLE `fza_facturas_consolidaciones` ADD INDEX `IDX_FECHA_PROCESAMIENTO_CONSOLIDACION` (`FECHA_PROCESAMIENTO_FACCON`);
ALTER TABLE `fza_facturas_consolidaciones` ADD INDEX `IDX_REQUEST_ID` (`REQUEST_ID_CONSOLIDACION_FACCON`);
ALTER TABLE `fza_facturas_consolidaciones` ADD UNIQUE INDEX `UK_FACTURA` (`SERIE_FAC_FACCON`, `NUMERO_FAC_FACCON`);


-- Tabla: fza_facturas_lineas

DROP TABLE IF EXISTS `fza_facturas_lineas`;
CREATE TABLE `fza_facturas_lineas` (
  `NUMERO_FAC_FACLIN` varchar(20) NOT NULL,
  `SERIE_FAC_FACLIN` varchar(20) NOT NULL,
  `CODIGO_EMP_FACLIN` varchar(8) NULL DEFAULT NULL,
  `LINEA_FACLIN` varchar(4) NOT NULL,
  `CODIGO_ART_FACLIN` varchar(20) NULL DEFAULT NULL,
  `CODIGO_UNIDAD_FACLIN` varchar(50) NULL DEFAULT NULL,
  `LOTE_FACLIN` varchar(50) NULL DEFAULT NULL,
  `FECHA_CADUCIDAD_FACLIN` date NULL DEFAULT NULL,
  `CODIGO_FAM_FACLIN` varchar(20) NULL DEFAULT NULL,
  `NOMBRE_FAM_FACLIN` varchar(200) NULL DEFAULT NULL,
  `PRECIO_ULT_COMPRA_FACLIN` decimal(19,6) NULL DEFAULT NULL,
  `CODIGO_PRV_FACLIN` varchar(20) NULL DEFAULT NULL,
  `RAZON_SOCIAL_PROVEEDOR_FACLIN` varchar(200) NULL DEFAULT NULL,
  `ESPROVEEDORPRINCIPAL_FACLIN` varchar(1) NULL DEFAULT NULL,
  `FECHA_ENTREGA_FACLIN` datetime NULL DEFAULT NULL,
  `TIPO_ARTICULO_FACLIN` varchar(10) NULL DEFAULT 'ESTANDAR' COMMENT 'ESTANDAR=Físico (Control Stock), SERVICIO=Intangible (Sin Stock), KIT=Pack',
  `TIPO_CANTIDAD_ARTICULO_FACLIN` varchar(20) NULL DEFAULT 'Uds',
  `CANTIDAD_FACLIN` decimal(19,6) NULL DEFAULT '1.000000',
  `DESCRIPCION_ARTICULO_FACLIN` varchar(100) NULL DEFAULT NULL,
  `DESCRIPCION_VARIACION_FACLIN` varchar(200) NULL DEFAULT NULL,
  `CODIGO_TAR_FACLIN` varchar(10) NULL DEFAULT NULL,
  `ESIMP_INCL_TARIFA_FACLIN` varchar(1) NULL DEFAULT 'S',
  `PRECIO_SALIDA_FACLIN` decimal(19,6) NULL DEFAULT NULL,
  `PORCENTAJE_DTO_FACLIN` decimal(19,6) NULL DEFAULT NULL,
  `PRECIO_DTO_FACLIN` decimal(19,6) NULL DEFAULT NULL,
  `PRECIO_VENTA_SIVA_ARTICULO_FACLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TIPO_IVA_ARTICULO_FACLIN` varchar(2) NULL DEFAULT 'N',
  `PORCENTAJE_IVA_FACLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_VENTA_CIVA_ARTICULO_FACLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_FACLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_FAC_SIVA_FACLIN` decimal(19,6) NULL DEFAULT NULL,
  `CODIGO_VENDEDOR_FACLIN` varchar(10) NULL DEFAULT NULL COMMENT 'Usuario que se lleva la comisión',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `CODIGO_ALM_FACLIN` varchar(10) NULL DEFAULT NULL,
  `CODIGO_CAJA_FACLIN` varchar(10) NULL DEFAULT NULL,
  `NUMERO_OPERACION_FACLIN` varchar(20) NULL DEFAULT NULL,
  `NUMERO_MOV_FACLIN` varchar(20) NULL DEFAULT NULL,
  PRIMARY KEY (`NUMERO_FAC_FACLIN`,`SERIE_FAC_FACLIN`,`LINEA_FACLIN`)
);
ALTER TABLE `fza_facturas_lineas` ADD INDEX `FT_FACLIN_DESC` (`DESCRIPCION_ARTICULO_FACLIN`);
ALTER TABLE `fza_facturas_lineas` ADD INDEX `IDX_FACLIN_OPERACION` (`CODIGO_EMP_FACLIN`, `CODIGO_ALM_FACLIN`, `CODIGO_CAJA_FACLIN`, `NUMERO_OPERACION_FACLIN`);
ALTER TABLE `fza_facturas_lineas` ADD INDEX `IDX_FAC_LIN_ARTICULO` (`CODIGO_ART_FACLIN`, `SERIE_FAC_FACLIN`);
ALTER TABLE `fza_facturas_lineas` ADD INDEX `IDX_FAC_LIN_FAMILIA` (`CODIGO_FAM_FACLIN`);

