-- Tabla: fza_facturas_pagos

DROP TABLE IF EXISTS `fza_facturas_pagos`;
CREATE TABLE `fza_facturas_pagos` (
  `SERIE_FAC_FACPAG` varchar(20) NOT NULL COMMENT 'Vinculo con Cabecera SERIE',
  `NUMERO_FAC_FACPAG` varchar(20) NOT NULL COMMENT 'Vinculo con Cabecera NRO',
  `LINEA_FACPAG` int(11) NOT NULL COMMENT 'Contador secuencial (1, 2, 3...) para permitir varios pagos',
  `TIPO_FACPAG` varchar(50) NULL DEFAULT 'EFECTIVO' COMMENT 'EFECTIVO, TARJETA, BONO_AYTO, VALE_TIENDA, ETC',
  `IMPORTE_FACPAG` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Cuantía pagada con este medio',
  `REFERENCIA_FACPAG` varchar(100) NULL DEFAULT NULL COMMENT 'Aquí guardas el CÓDIGO DE BARRAS del bono o ref de tarjeta',
  `DESCRIPCION_FACPAG` varchar(200) NULL DEFAULT NULL COMMENT 'Ej: Bono Comercio Campaña Navidad',
  `ENTIDAD_FACPAG` varchar(100) NULL DEFAULT NULL COMMENT 'Banco, Ayuntamiento X, Asoc. Comerciantes',
  `FECHA_FACPAG` datetime NULL DEFAULT NULL COMMENT 'Instante exacto del cobro',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`SERIE_FAC_FACPAG`,`NUMERO_FAC_FACPAG`,`LINEA_FACPAG`)
);
ALTER TABLE `fza_facturas_pagos` ADD INDEX `IDX_FECHA_PAGO` (`FECHA_FACPAG`);
ALTER TABLE `fza_facturas_pagos` ADD INDEX `IDX_TIPO_PAGO` (`TIPO_FACPAG`);

