-- Tabla: fza_pedidos

DROP TABLE IF EXISTS `fza_pedidos`;
CREATE TABLE `fza_pedidos` (
  `NUMERO_PED` varchar(12) NOT NULL,
  `SERIE_PED` varchar(12) NOT NULL,
  `FECHA_PED` date NULL DEFAULT NULL,
  `ESCONSOLIDADO_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'S si el pedido ya no se puede modificar (todo entregado o cerrado)',
  `ESTADO_PED` varchar(20) NULL DEFAULT 'ABIERTO' COMMENT 'ABIERTO, PARCIAL, ENTREGADO, CANCELADO, IMPORTADO',
  `FECHA_ENTREGA_PED` date NULL DEFAULT NULL COMMENT 'Fecha prevista de entrega del pedido',
  `CODIGO_EMP_PED` varchar(8) NULL DEFAULT NULL,
  `RAZON_SOCIAL_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `NIF_EMPRESA_PED` varchar(50) NULL DEFAULT NULL,
  `MOVIL_EMPRESA_PED` varchar(40) NULL DEFAULT NULL,
  `EMAIL_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `DIRECCION1_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `POBLACION_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_EMPRESA_PED` varchar(200) NULL DEFAULT NULL,
  `CODIGO_PAI_EMPRESA_PED` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_EMPRESA_PED` varchar(150) NULL DEFAULT 'España',
  `CODIGO_POSTAL_EMPRESA_PED` varchar(15) NULL DEFAULT NULL,
  `ESRETENCIONES_EMPRESA_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'S o N si la empresa aplica retenciones como autónomos',
  `GRUPO_ZONA_IVA_EMPRESA_PED` varchar(10) NULL DEFAULT NULL,
  `ESREGIMENESPECIALAGRICOLA_EMPRESA_PED` varchar(1) NULL DEFAULT 'N',
  `CODIGO_CLI_PED` varchar(10) NULL DEFAULT NULL,
  `NIF_CLIENTE_PED` varchar(50) NULL DEFAULT NULL,
  `EMAIL_CLIENTE_PED` varchar(200) NULL DEFAULT NULL,
  `REFERENCIAPS_PED` varchar(20) NULL DEFAULT NULL,
  `IDPS_PED` varchar(20) NULL DEFAULT NULL,
  `FECHAPS_PED` datetime NULL DEFAULT NULL,
  `FORMAPAGOPS_PED` varchar(200) NULL DEFAULT NULL,
  `TRANSPORTISTAPS_PED` varchar(200) NULL DEFAULT NULL,
  `ESTADOPEDIDOPS_PED` varchar(300) NULL DEFAULT NULL,
  `ESTADOMENSAJEPS_PED` varchar(300) NULL DEFAULT NULL,
  `IDHILOPS_MENSAJES_PED` varchar(20) NULL DEFAULT NULL,
  `NOMBRE_CLI_ENVIO_PED` varchar(200) NULL DEFAULT NULL,
  `MOVIL_CLIENTE_ENVIO_PED` varchar(40) NULL DEFAULT NULL,
  `DIRECCION1_CLIENTE_ENVIO_PED` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_CLIENTE_ENVIO_PED` varchar(200) NULL DEFAULT NULL,
  `POBLACION_CLIENTE_ENVIO_PED` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_CLIENTE_ENVIO_PED` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_ENVIO_PED` varchar(15) NULL DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_ENVIO_PED` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_ENVIO_PED` varchar(150) NULL DEFAULT 'España',
  `RAZON_SOCIAL_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `MOVIL_CLIENTE_FISCAL_PED` varchar(40) NULL DEFAULT NULL,
  `EMAIL_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `DIRECCION1_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `DIRECCION2_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `POBLACION_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `PROVINCIA_CLIENTE_FISCAL_PED` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_CLIENTE_FISCAL_PED` varchar(15) NULL DEFAULT NULL,
  `CODIGO_PAI_CLIENTE_FISCAL_PED` varchar(3) NULL DEFAULT '724',
  `NOMBRE_PAI_CLIENTE_FISCAL_PED` varchar(150) NULL DEFAULT 'España',
  `ESIVA_RECARGO_CLIENTE_PED` varchar(1) NULL DEFAULT 'N',
  `ESIVA_EXENTO_CLIENTE_PED` varchar(1) NULL DEFAULT 'N',
  `ESREGIMENESPECIALAGRICOLA_CLIENTE_PED` varchar(1) NULL DEFAULT 'N',
  `ESRETENCIONES_CLIENTE_PED` varchar(1) NULL DEFAULT 'S' COMMENT 'S o N Si el cliente aplica retenciones',
  `TARIFA_ARTICULO_CLIENTE_PED` varchar(10) NULL DEFAULT NULL COMMENT 'Código de la tarifa que viene del cliente o configurada por el usuario',
  `ESIMP_INCL_TARIFA_CLIENTE_PED` varchar(1) NULL DEFAULT 'S' COMMENT 'Si el precio de la tarifa del cliente es con impuestos incl o no',
  `ESINTRACOMUNITARIO_CLIENTE_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'Si la venta es hacia un país de la UE',
  `ESIRPF_IMP_INCL_ZONA_IVA_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'Si la base del cáculo del irpf se hace desde BI o BI con impuestos',
  `ESAPLICA_RE_ZONA_IVA_PED` varchar(1) NULL DEFAULT 'S' COMMENT 'Si el tipo de IVA aplica Recargo de Equivalencia o no',
  `ESIVAAGRICOLA_ZONA_IVA_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'Si el tipo de IVA es compatible con REAGP',
  `PALABRA_REPORTS_ZONA_IVA_PED` varchar(10) NULL DEFAULT 'IVA' COMMENT 'Palabra que sustituye a IVA desde la tabla de fza_ivas_grupos',
  `CODIGO_IVA_PED` varchar(20) NULL DEFAULT NULL COMMENT 'Código de IVA de la tabla fza_ivas',
  `ESVENTA_ACTIVO_FIJO_PED` varchar(1) NULL DEFAULT 'N' COMMENT 'Sólo REAGP cuando se vende activos fijos, exime irpf',
  `PORCENTAJE_IVAN_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Normal',
  `TOTAL_IVAN_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA Normal',
  `PORCENTAJE_REN_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje RE Normal',
  `TOTAL_REN_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Normal',
  `TOTAL_BASEI_IVAN_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Base Imponible IVA Normal',
  `PORCENTAJE_IVAR_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Reducido',
  `TOTAL_IVAR_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'TotaL IVA Reducido',
  `PORCENTAJE_RER_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje RE Reducido',
  `TOTAL_RER_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Reducido',
  `TOTAL_BASEI_IVAR_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Base Imponible IVA Reducido',
  `PORCENTAJE_IVAS_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_IVAS_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA SuperReducido',
  `PORCENTAJE_RES_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA SuperReducido',
  `TOTAL_RES_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE SuperReducido',
  `TOTAL_BASEI_IVAS_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total sin IVA SuperReducido',
  `PORCENTAJE_IVAE_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA Exento',
  `TOTAL_IVAE_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total IVA Exento',
  `PORCENTAJE_REE_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje IVA1 Exento',
  `TOTAL_REE_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Total RE Exento',
  `TOTAL_BASEI_IVAE_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total sin IVA Exento',
  `TOTAL_BASES_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Todas las bases imponibles',
  `TOTAL_IMPUESTOS_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total de todos los impuestos iva + re',
  `FORMA_PAGO_PED` varchar(200) NULL DEFAULT NULL COMMENT 'Codigo Forma de Pago',
  `PORCENTAJE_RETENCION_PED` decimal(19,6) NULL DEFAULT NULL COMMENT 'Porcentaje Retenciones',
  `TOTAL_RETENCION_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total Retenciones PEDIDO',
  `TOTAL_LIQUIDO_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total PEDIDO a pagar',
  `TOTAL_PAGADOREALPS_PED` decimal(18,6) NULL DEFAULT NULL COMMENT 'Total pagado cliente',
  `NUMERO_PED_ABONO_PED` varchar(8) NULL DEFAULT NULL COMMENT 'Nro PEDIDO Abono',
  `SERIE_PED_ABONO_PED` varchar(8) NULL DEFAULT NULL COMMENT 'Serie PEDIDO Abono',
  `TEXTO_LEGAL_CLIENTE_PED` varchar(1000) NULL DEFAULT '',
  `TEXTO_LEGAL_EMPRESA_PED` varchar(1000) NULL DEFAULT '',
  `DOCUMENTO_PED` blob NULL DEFAULT NULL COMMENT 'Copia en PDF del documento final',
  `COMENTARIOS_PED` varchar(1000) NULL DEFAULT '',
  `OBSERVACIONES_PED` varchar(2000) NULL DEFAULT '',
  `CONTADOR_LINEAS_PED` varchar(8) NULL DEFAULT NULL COMMENT 'Contador de lineas para lineas de PEDIDO',
  `ESCREARARTICULOS_PED` varchar(1) NULL DEFAULT NULL COMMENT 'S o N si se crean articulos desde el detalle',
  `ESDESCRIPCIONES_AMP_PED` varchar(1) NULL DEFAULT 'S' COMMENT 'S o N si la PEDIDO contiene una descripción larga',
  `ESFECHADEENTREGA_PED` varchar(1) NULL DEFAULT NULL COMMENT 'S o N si las descripciones tienen fecha de entrega',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`NUMERO_PED`,`SERIE_PED`)
);
ALTER TABLE `fza_pedidos` ADD INDEX `IDX_PED_CLIENTE_FECHA` (`CODIGO_CLI_PED`, `FECHA_PED`);
ALTER TABLE `fza_pedidos` ADD INDEX `IDX_PED_EMPRESA` (`CODIGO_EMP_PED`);
ALTER TABLE `fza_pedidos` ADD INDEX `IDX_PED_ESTADO` (`ESTADO_PED`);
